export function toSelectRequestCborValue(v: SelectRequest): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  if (v.task !== undefined) csilMap.set("task", v.task);
  if (v.limit !== undefined) csilMap.set("limit", v.limit);
  if (v.strict !== undefined) csilMap.set("strict", v.strict);
  if (v.selector !== undefined) csilMap.set("selector", toSelectorCborValue(v.selector));
  return csilMap;
}

export function fromSelectRequestCborValue(value: CborValue): SelectRequest {
  return {
    task: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "task")),
    selector: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : fromSelectorCborValue(csilV))(mapGet(value, "selector")),
    limit: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "limit")),
    strict: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asBool(csilV))(mapGet(value, "strict")),
  };
}

export function toSelectRequestCbor(v: SelectRequest): Uint8Array {
  return encodeValue(toSelectRequestCborValue(v));
}

export function fromSelectRequestCbor(bytes: Uint8Array): SelectRequest {
  return fromSelectRequestCborValue(decode(bytes));
}

export function toCandidateCborValue(v: Candidate): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("model", toModelCborValue(v.model));
  csilMap.set("reason", v.reason);
  return csilMap;
}

export function fromCandidateCborValue(value: CborValue): Candidate {
  return {
    model: fromModelCborValue(requireKey(value, "model")),
    reason: asString(requireKey(value, "reason")),
  };
}

export function toCandidateCbor(v: Candidate): Uint8Array {
  return encodeValue(toCandidateCborValue(v));
}

export function fromCandidateCbor(bytes: Uint8Array): Candidate {
  return fromCandidateCborValue(decode(bytes));
}

export function toSelectResponseCborValue(v: SelectResponse): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("selector", toSelectorCborValue(v.selector));
  csilMap.set("candidates", v.candidates.map((csilE): CborValue => toCandidateCborValue(csilE)));
  return csilMap;
}

export function fromSelectResponseCborValue(value: CborValue): SelectResponse {
  return {
    candidates: asArray(requireKey(value, "candidates")).map((csilE) => fromCandidateCborValue(csilE)),
    selector: fromSelectorCborValue(requireKey(value, "selector")),
  };
}

export function toSelectResponseCbor(v: SelectResponse): Uint8Array {
  return encodeValue(toSelectResponseCborValue(v));
}

export function fromSelectResponseCbor(bytes: Uint8Array): SelectResponse {
  return fromSelectResponseCborValue(decode(bytes));
}

